      { id: "c", text: "Give an intravenous bolus of atropine one milligram and repeat it to a maximum of three milligrams while the monitor is watched" },
      { id: "d", text: "Infuse five hundred millilitres of normal saline over ten minutes to restore blood flow to the carotid arteries" }
